warp:
shader_body
{
vec2 _uv = uv;

    // sample previous frame
    ret = texture( sampler_fc_main, _uv ).xyz;
vec4 noise9 = texture(sampler_noisevol_hq, 
                      ((_uv.xyy*q27 )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      vec3(1.0,1.0,0.0)*0.05 + 
                      time*vec3(0.0,0.0,1.0)*q29
                     ).xyz;
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y -= (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z -= (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x -= (noise9).z*.5; 

    // darken (decay) over time
    ret *= 0.95; //or try: ret -= 0.004;

}

comp:
shader_body
{

uv = 0.5 + (uv-0.5)*0.98;
    vec2 d = texsize.zw*4.0;
    vec3 dx = ( ((texture(sampler_blur1, uv+vec2(1.0,0.0)*d).xyz * scale1) + bias1)-((texture(sampler_blur1, uv-vec2(1.0,0.0)*d).xyz * scale1) + bias1) );
    vec3 dy = ( ((texture(sampler_blur1, uv+vec2(0.0,1.0)*d).xyz * scale1) + bias1)-((texture(sampler_blur1, uv-vec2(0.0,1.0)*d).xyz * scale1) + bias1) );

vec4 noise = texture(sampler_noisevol_hq, ((uv.xyy+vec3(lum(dx),lum(dy),0.0)*0.5)*texsize.xyy*texsize_noisevol_hq.zww).xyz*vec3(1.0,1.0,0.0)*0.05 + time*vec3(0.0,0.0,1.0)*0.2 ).xyz;
uv -= vec2(lum(dx),lum(dy))*0.04;
ret = abs(texture(sampler_main, uv).xyz+((texture(sampler_blur1, uv).xyz * scale1) + bias1)-((texture(sampler_blur2, uv).xyz * scale2) + bias2)-((texture(sampler_blur3, uv).xyz * scale3) + bias3));
ret *= lum(noise)*3.0; 
ret = pow(ret,0.5);
ret=1.0-ret;
}
